2	import { execFileSync } from "node:child_process";
3	import { join, normalize, resolve } from "node:path";
4	import type { WorktreeInitResult, WorktreePullResult, WorktreeSyncResult } from "../types";
5	import { AgentrackError, ErrorCodes } from "./errors";
6	import type { WorktreeOptions } from "./branch-config";
7	
8	/** Default branch name used for the agentrack data worktree. */
9	export const DEFAULT_BRANCH = "_agentrack";
10	
11	/** Default directory name for the agentrack data worktree. */
12	export const DEFAULT_DIR = ".agentrack";
13	
14	/** @deprecated Use DEFAULT_BRANCH instead. */
15	export const WORKTREE_BRANCH = DEFAULT_BRANCH;
16	
17	/** @deprecated Use DEFAULT_DIR instead. */
18	export const WORKTREE_DIR = DEFAULT_DIR;
19	
20	/**
21	 * Default file contents for the orphan branch.
22	 * These match the Tracker.init() defaults exactly.
23	 */
24	const DEFAULT_CONFIG = { auth: { mode: "open", defaultUser: "anonymous" } };
25	const DEFAULT_INDEX = { open: [], closed: [], childrenOf: {} };
26	const DEFAULT_DEPENDENCIES = { blockedBy: {}, blocks: {} };
27	const DEFAULT_USERS = { users: [] };
28	
29	// ─── Git helpers ─────────────────────────────────────────────────────
30	
31	/**
32	 * Execute a git command synchronously using array-based argument passing.
33	 * Uses execFileSync to avoid shell injection.
34	 */
35	function gitExec(cwd: string, args: string[]): string {
36	  return execFileSync("git", args, { cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
37	}
38	
39	/**
40	 * Extract stderr from an execFileSync error.
41	 */
42	function getGitError(err: unknown): string {
43	  if (typeof err === "object" && err !== null && "stderr" in err) {
44	    const stderr = (err as { stderr: unknown }).stderr;
45	    if (typeof stderr === "string") return stderr;
46	  }
47	  return (err as Error).message || String(err);
48	}
49	
50	/**
51	 * Check if `cwd` is inside a git repository.
52	 */
53	function isGitRepo(cwd: string): boolean {
54	  try {
55	    gitExec(cwd, ["rev-parse", "--git-dir"]);
56	    return true;
57	  } catch {
58	    return false;
59	  }
60	}
61	
62	/**
63	 * Get the current branch name.
64	 */
65	function getCurrentBranch(cwd: string): string {
66	  return gitExec(cwd, ["rev-parse", "--abbrev-ref", "HEAD"]).trim();
67	}
68	
69	/**
70	 * Check if a remote named 'origin' is configured.
71	 */
72	function hasRemote(cwd: string): boolean {
73	  try {
74	    const remotes = gitExec(cwd, ["remote"]);
75	    return remotes.split("\n").some((r) => r.trim() === "origin");
76	  } catch {
77	    return false;
78	  }
79	}
80	
81	/**
82	 * Create a blob object from content via stdin.
83	 * Returns the blob hash.
84	 */
85	function gitHashObject(cwd: string, content: string): string {
86	  // execFileSync supports Buffer input via input option
87	  return execFileSync("git", ["hash-object", "-w", "--stdin"], {
88	    cwd,
89	    encoding: "utf-8",
90	    input: content,
91	    stdio: ["pipe", "pipe", "pipe"],
92	  }).trim();
93	}
94	
95	/**
96	 * Create a tree object from formatted entries.
97	 */
98	function gitMkTree(cwd: string, entries: string): string {
99	  return execFileSync("git", ["mktree"], {
100	    cwd,
101	    encoding: "utf-8",
102	    input: entries,
103	    stdio: ["pipe", "pipe", "pipe"],
104	  }).trim();
105	}
106	
107	/**
108	 * Create a commit from a tree hash.
109	 */
110	function gitCommitTree(cwd: string, tree: string, message: string): string {
111	  return execFileSync("git", ["commit-tree", tree, "-m", message], {
112	    cwd,
113	    encoding: "utf-8",
114	    stdio: ["pipe", "pipe", "pipe"],
115	  }).trim();
116	}
117	
118	// ─── Gitignore helpers ───────────────────────────────────────────────
119	
120	/**
121	 * Check if the gitignore content already has an entry for the given directory.
122	 * Matches common patterns: /dir/, dir/, /dir, dir
123	 */
124	function gitignoreHasEntry(content: string, dir: string): boolean {
125	  return content.split("\n").some((rawLine) => {
126	    const line = rawLine.trim();
127	    // Skip comments and empty lines
128	    if (!line || line.startsWith("#")) return false;
129	    return (
130	      line === `/${dir}/` ||
131	      line === `${dir}/` ||
132	      line === `/${dir}` ||
133	      line === dir
134	    );
135	  });
136	}
137	
138	/**
139	 * Ensure .gitignore has an entry for the given directory.
140	 * Appends the entry if missing. Does NOT stage or commit.
141	 * Returns true if an entry was added.
142	 */
143	function ensureGitignoreEntry(cwd: string, dir: string): boolean {
144	  const gitignorePath = join(cwd, ".gitignore");
145	  if (existsSync(gitignorePath)) {
146	    const content = readFileSync(gitignorePath, "utf-8");
147	    if (gitignoreHasEntry(content, dir)) {
148	      return false;
149	    }
150	    // Append entry (ensure newline before if file doesn't end with one)
151	    const suffix = content.endsWith("\n") ? "" : "\n";
152	    writeFileSync(gitignorePath, `${content}${suffix}/${dir}/\n`, "utf-8");
153	  } else {
154	    writeFileSync(gitignorePath, `/${dir}/\n`, "utf-8");
155	  }
156	  return true;
157	}
158	
159	// ─── Precondition checks ─────────────────────────────────────────────
160	
161	/**
162	 * Validate preconditions before worktree initialization.
163	 * Throws AgentrackError if any precondition fails.
164	 */
165	function checkPreconditions(cwd: string, opts: WorktreeOptions): void {
166	  // Must be inside a git repo
167	  if (!isGitRepo(cwd)) {
168	    throw new AgentrackError(
169	      ErrorCodes.NOT_A_GIT_REPO.result,
170	      "Not inside a git repository",
171	      ErrorCodes.NOT_A_GIT_REPO.exitCode,
172	    );
173	  }
174	
175	  // Worktree dir must not exist as a non-worktree (legacy)
176	  const agentrackPath = join(cwd, opts.dir);
177	  if (existsSync(agentrackPath)) {
178	    const stat = statSync(agentrackPath);
179	    if (!stat.isDirectory()) {
180	      throw new AgentrackError(
181	        ErrorCodes.MIGRATION_REQUIRED.result,
182	        `${opts.dir} exists but is not a directory. Remove it and re-run init.`,
183	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
184	      );
185	    }
186	    // Directory exists — if not a worktree, it's a legacy directory
187	    if (!isWorktreeInitialized(cwd, opts)) {
188	      throw new AgentrackError(
189	        ErrorCodes.MIGRATION_REQUIRED.result,
190	        `${opts.dir}/ exists but is not a git worktree. Remove it manually and re-run init.`,
191	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
192	      );
193	    }
194	    // If it IS a valid worktree, caller should handle ALREADY_INITIALIZED
195	  }
196	
197	  // Must not be on the target branch
198	  const currentBranch = getCurrentBranch(cwd);
199	  if (currentBranch === opts.branch) {
200	    throw new AgentrackError(
201	      ErrorCodes.INVALID_STATE.result,
202	      `Cannot init: currently on the ${opts.branch} branch. Switch to a code branch first.`,
203	      ErrorCodes.INVALID_STATE.exitCode,
204	    );
205	  }
206	
207	  // Check if branch already exists locally with non-agentrack data
208	  try {
209	    const existingCommit = gitExec(cwd, ["rev-parse", "--verify", opts.branch]).trim();
210	    // Branch exists — validate it contains agentrack data
211	    const files = gitExec(cwd, ["ls-tree", "--name-only", existingCommit]).trim();
212	    const fileList = files
213	      .split("\n")
214	      .map((f) => f.trim())
215	      .filter(Boolean);
216	    const expectedFiles = ["config.json", "index.json", "dependencies.json", "users.json"];
217	    const hasAgentrackData = expectedFiles.every((f) => fileList.includes(f));
218	
219	    if (!hasAgentrackData) {
220	      throw new AgentrackError(
221	        ErrorCodes.BRANCH_CONFLICT.result,
222	        `Branch '${opts.branch}' already exists but does not contain agentrack data`,
223	        ErrorCodes.BRANCH_CONFLICT.exitCode,
224	      );
225	    }
226	    // Branch exists with agentrack data — allow re-init (re-creation of worktree)
227	  } catch (err) {
228	    // If it's our BRANCH_CONFLICT error, re-throw it
229	    if (err instanceof AgentrackError) throw err;
230	    // rev-parse failed — branch doesn't exist locally, proceed with creation
231	  }
232	}
233	
234	// ─── Public API ──────────────────────────────────────────────────────
235	
236	/**
237	 * Detect which init scenario applies: 'fresh' (no remote branch) or 'join' (remote branch exists).
238	 */
239	export function detectInitScenario(cwd: string, opts?: WorktreeOptions): "fresh" | "join" {
240	  const { branch } = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
241	  try {
242	    const result = gitExec(cwd, ["ls-remote", "--heads", "origin", branch]);
243	    return result.trim().length > 0 ? "join" : "fresh";
244	  } catch {
245	    // No remote or no connectivity → fresh
246	    return "fresh";
247	  }
248	}
249	
250	/**
251	 * Check if the worktree directory is a valid git worktree for the target branch.
252	 * When opts is not provided, uses default branch/dir.
253	 */
254	export function isWorktreeInitialized(cwd: string, opts?: WorktreeOptions): boolean {
255	  const { dir } = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
256	  try {
257	    const worktreeList = gitExec(cwd, ["worktree", "list", "--porcelain"]);
258	    const normalizedCwd = resolve(cwd);
259	    const expectedPath = normalize(join(normalizedCwd, dir));
260	
261	    return worktreeList.split("\n").some((line) => {
262	      if (!line.startsWith("worktree ")) return false;
263	      const wtPath = line.slice("worktree ".length);
264	      return normalize(wtPath) === expectedPath;
265	    });
266	  } catch {
267	    return false;
268	  }
269	}
270	
271	/**
272	 * Scenario A: create orphan branch with initial data, push, mount worktree.
273	 * Uses git plumbing commands to avoid modifying the working tree.
274	 */
275	export function initFreshWorktree(cwd: string, opts?: WorktreeOptions): WorktreeInitResult {
276	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
277	  // 1. Create blob objects for initial files
278	  const configBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_CONFIG, null, 2)}\n`);
279	  const indexBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_INDEX, null, 2)}\n`);
280	  const depsBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_DEPENDENCIES, null, 2)}\n`);
281	  const usersBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_USERS, null, 2)}\n`);
282	
283	  // 2. Create a tree object referencing these blobs
284	  const treeInput = [
285	    `100644 blob ${configBlob}\tconfig.json`,
286	    `100644 blob ${indexBlob}\tindex.json`,
287	    `100644 blob ${depsBlob}\tdependencies.json`,
288	    `100644 blob ${usersBlob}\tusers.json`,
289	  ].join("\n");
290	  const tree = gitMkTree(cwd, treeInput);
291	
292	  // 3. Create a commit from the tree
293	  const commit = gitCommitTree(cwd, tree, `init ${worktreeOpts.branch} branch`);
294	
295	  // 4. Create the branch ref
296	  try {
297	    gitExec(cwd, ["branch", worktreeOpts.branch, commit]);
298	  } catch (err) {
299	    // Branch might already exist from a failed previous attempt
300	    const stderr = getGitError(err);
301	    if (stderr.includes("already exists")) {
302	      // Force-update the branch to our new commit
303	      gitExec(cwd, ["branch", "-f", worktreeOpts.branch, commit]);
304	    } else {
305	      throw new AgentrackError(
306	        ErrorCodes.INVALID_STATE.result,
307	        `Failed to create branch: ${stderr}`,
308	        ErrorCodes.INVALID_STATE.exitCode,
309	      );
310	    }
311	  }
312	
313	  // 5. Push to remote (if available)
314	  if (hasRemote(cwd)) {
315	    try {
316	      gitExec(cwd, ["push", "-u", "origin", worktreeOpts.branch]);
317	    } catch (pushErr) {
318	      const stderr = getGitError(pushErr);
319	      // If push fails because branch already exists remotely, fall back to join
320	      if (
321	        stderr.includes("already exists") ||
322	        stderr.includes("failed to push") ||
323	        stderr.includes("non-fast-forward")
324	      ) {
325	        return initJoinWorktree(cwd, worktreeOpts);
326	      }
327	      // Network or other errors — proceed with local branch only (warn implicitly)
328	    }
329	  }
330	
331	  // 6. Ensure .gitignore entry
332	  ensureGitignoreEntry(cwd, worktreeOpts.dir);
333	
334	  // 7. Mount worktree
335	  try {
336	    gitExec(cwd, ["worktree", "add", worktreeOpts.dir, worktreeOpts.branch]);
337	  } catch (err) {
338	    const stderr = getGitError(err);
339	    throw new AgentrackError(
340	      ErrorCodes.INVALID_STATE.result,
341	      `Failed to mount worktree: ${stderr}`,
342	      ErrorCodes.INVALID_STATE.exitCode,
343	    );
344	  }
345	
346	  return { scenario: "fresh", path: resolve(cwd, worktreeOpts.dir) };
347	}
348	
349	/**
350	 * Scenario B: fetch remote branch, create tracking branch, mount worktree.
351	 */
352	export function initJoinWorktree(cwd: string, opts?: WorktreeOptions): WorktreeInitResult {
353	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
354	  // 1. Fetch the remote branch
355	  try {
356	    gitExec(cwd, ["fetch", "origin", worktreeOpts.branch]);
357	  } catch (err) {
358	    const stderr = getGitError(err);
359	    throw new AgentrackError(
360	      ErrorCodes.INVALID_STATE.result,
361	      `Failed to fetch remote branch: ${stderr}`,
362	      ErrorCodes.INVALID_STATE.exitCode,
363	    );
364	  }
365	
366	  // 2. Create local tracking branch
367	  try {
368	    gitExec(cwd, ["branch", worktreeOpts.branch, `origin/${worktreeOpts.branch}`]);
369	  } catch {
370	    // Branch might already exist — force-update to remote ref
371	    try {
372	      gitExec(cwd, ["branch", "-f", worktreeOpts.branch, `origin/${worktreeOpts.branch}`]);
373	    } catch (err) {
374	      const stderr = getGitError(err);
375	      throw new AgentrackError(
376	        ErrorCodes.INVALID_STATE.result,
377	        `Failed to create tracking branch: ${stderr}`,
378	        ErrorCodes.INVALID_STATE.exitCode,
379	      );
380	    }
381	  }
382	
383	  // 3. Ensure .gitignore entry
384	  ensureGitignoreEntry(cwd, worktreeOpts.dir);
385	
386	  // 4. Mount worktree
387	  try {
388	    gitExec(cwd, ["worktree", "add", worktreeOpts.dir, worktreeOpts.branch]);
389	  } catch (err) {
390	    const stderr = getGitError(err);
391	    throw new AgentrackError(
392	      ErrorCodes.INVALID_STATE.result,
393	      `Failed to mount worktree: ${stderr}`,
394	      ErrorCodes.INVALID_STATE.exitCode,
395	    );
396	  }
397	
398	  return { scenario: "join", path: resolve(cwd, worktreeOpts.dir) };
399	}
400	
401	/**
402	 * Initialize the agentrack worktree. Performs precondition checks, detects the
403	 * scenario, and delegates to the appropriate setup function.
404	 *
405	 * Returns the init result, or throws AgentrackError on failure.
406	 *
407	 * When opts is not provided, uses default branch/dir.
408	 */
409	export function initWorktree(cwd: string, opts?: WorktreeOptions): WorktreeInitResult {
410	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
411	
412	  // Check if already initialized
413	  if (isWorktreeInitialized(cwd, worktreeOpts)) {
414	    return { scenario: "already_initialized", path: resolve(cwd, worktreeOpts.dir) };
415	  }
416	
417	  // Validate preconditions (throws on failure)
418	  checkPreconditions(cwd, worktreeOpts);
419	
420	  // Detect scenario and delegate
421	  const scenario = detectInitScenario(cwd, worktreeOpts);
422	  if (scenario === "fresh") {
423	    return initFreshWorktree(cwd, worktreeOpts);
424	  }
425	  return initJoinWorktree(cwd, worktreeOpts);
426	}
427	
428	/**
429	 * Stage and commit .gitignore changes (and pointer file if present) on the current code branch.
430	 * Used after initWorktree() to persist the worktree dir gitignore entry and pointer file.
431	 * No-op if there are no changes to commit.
432	 */
433	export function commitGitignoreChange(cwd: string, dir?: string): void {
434	  const entry = dir ?? DEFAULT_DIR;
435	  try {
436	    gitExec(cwd, ["add", ".gitignore"]);
437	    // Also stage pointer file if it exists
438	    if (existsSync(join(cwd, ".agentrack.json"))) {
439	      gitExec(cwd, ["add", ".agentrack.json"]);
440	    }
441	    gitExec(cwd, ["commit", "-m", `chore: add ${entry}/ to .gitignore`]);
442	  } catch {
443	    // No changes to commit or .gitignore unchanged
444	  }
445	}
446	
447	/**
448	 * Stage all changes in the worktree and commit them with the given message.
449	 * Used after tracker.init() to persist initial data to the worktree branch.
450	 */
451	export function commitWorktreeData(cwd: string, message: string, opts?: WorktreeOptions): void {
452	  const dir = opts?.dir ?? DEFAULT_DIR;
453	  const worktreeDir = join(cwd, dir);
454	  gitExec(worktreeDir, ["add", "-A"]);
455	  try {
456	    gitExec(worktreeDir, ["commit", "-m", message]);
457	  } catch {
458	    // No changes to commit — that's fine (e.g., data already committed)
459	  }
460	}
461	
462	/**
463	 * Stage all changes, auto-commit, and push to remote.
464	 *
465	 * When opts is not provided, resolves branch from pointer file or defaults.
466	 */
467	export function pushWorktree(cwd: string, message?: string, opts?: WorktreeOptions): WorktreeSyncResult {
468	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
469	  const worktreeDir = join(cwd, worktreeOpts.dir);
470	
471	  // Verify worktree is initialized
472	  if (!isWorktreeInitialized(cwd, worktreeOpts)) {
473	    throw new AgentrackError(
474	      ErrorCodes.NOT_INITIALIZED.result,
475	      "Agentrack not initialized. Run `agt init` first.",
476	      ErrorCodes.NOT_INITIALIZED.exitCode,
477	    );
478	  }
479	
480	  // Stage all changes
481	  gitExec(worktreeDir, ["add", "-A"]);
482	
483	  // Check for staged changes
484	  let hasStagedChanges = false;
485	  try {
486	    gitExec(worktreeDir, ["diff", "--cached", "--quiet"]);
487	    // Exit code 0 = no diff = no staged changes
488	  } catch {
489	    // Exit code 1 = there are staged changes
490	    hasStagedChanges = true;
491	  }
492	
493	  if (hasStagedChanges) {
494	    // Commit staged changes
495	    const commitMessage =
496	      message || `sync: ${new Date().toISOString()}`;
497	    try {
498	      gitExec(worktreeDir, ["commit", "-m", commitMessage]);
499	    } catch (err) {
500	      const stderr = getGitError(err);
501	      throw new AgentrackError(
502	        ErrorCodes.PUSH_FAILED.result,
503	        `git commit failed: ${stderr}`,
504	        ErrorCodes.PUSH_FAILED.exitCode,
505	      );
506	    }
507	  }
508	
509	  // Check if there's anything to push
510	  let hasUnpushedCommits = false;
511	  try {
512	    const count = gitExec(worktreeDir, ["rev-list", "--count", "@{upstream}..HEAD"]).trim();
513	    hasUnpushedCommits = parseInt(count, 10) > 0;
514	  } catch {
515	    // No upstream set — means we need to push
516	    hasUnpushedCommits = true;
517	  }
518	
519	  if (!hasStagedChanges && !hasUnpushedCommits) {
520	    return { synced: false, message: "No changes to sync" };
521	  }
522	
523	  // Push to remote
524	  if (hasRemote(cwd)) {
525	    try {
526	      gitExec(worktreeDir, ["push"]);
527	    } catch (err) {
528	      const stderr = getGitError(err);
529	      throw new AgentrackError(
530	        ErrorCodes.PUSH_FAILED.result,
531	        `git push failed: ${stderr}`,
532	        ErrorCodes.PUSH_FAILED.exitCode,
533	      );
534	    }
535	  }
536	
537	  return {
538	    synced: true,
539	    commitCount: hasStagedChanges ? 1 : 0,
540	  };
541	}
542	
543	/**
544	 * Pull latest from remote into the worktree.
545	 *
546	 * When opts is not provided, resolves branch from pointer file or defaults.
547	 */
548	export function pullWorktree(cwd: string, opts?: WorktreeOptions): WorktreePullResult {
549	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
550	  const worktreeDir = join(cwd, worktreeOpts.dir);
551	
552	  // Verify worktree is initialized
553	  if (!isWorktreeInitialized(cwd, worktreeOpts)) {
554	    throw new AgentrackError(
555	      ErrorCodes.NOT_INITIALIZED.result,
556	      "Agentrack not initialized. Run `agt init` first.",
557	      ErrorCodes.NOT_INITIALIZED.exitCode,
558	    );
559	  }
560	
561	  try {
562	    const output = gitExec(worktreeDir, ["pull"]);
563	    // "Already up to date." means no updates
564	    const updated = !output.includes("Already up to date");
565	    return { updated };
566	  } catch (err) {
567	    const stderr = getGitError(err);
568	    throw new AgentrackError(
569	      ErrorCodes.PULL_FAILED.result,
570	      `git pull failed: ${stderr}`,
571	      ErrorCodes.PULL_FAILED.exitCode,
572	    );
573	  }
574	}
