/**
 * Get the project root directory using git.
 */
function getProjectRoot(): string {
  return execSync("git rev-parse --show-toplevel", {
    encoding: "utf-8",
    cwd: import.meta.dir,
  }).trim();
}

/**
 * Get the absolute path to the validation/ directory.
 * Creates it if it doesn't exist.
 */
export function getValidationDir(): string {
  const dir = join(getProjectRoot(), "validation");
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
  return dir;
}

/**
 * Get the tracker data directory for a branch.
 * e.g., for branch "e2edata" → validation/.e2edata/
 */
export function getTrackerDir(branch: string): string {
  return join(getValidationDir(), `.${branch}`);
}

/**
 * Get the git branch name for a test branch.
 * e.g., "e2edata" → "_e2edata"
