    await ensureE2EWorktree(E2E_DATA_BRANCH);
  });

  beforeEach(() => {
    resetWorktreeData(E2E_DATA_BRANCH);
  });

  test("returns the best issue for a user", async () => {
    await runAgt([
      "create",
      "Low Priority",
      "--assignee",
      "alice",
      "--priority",
      "5",
      "--status",
      "todo",
