    let list = parseJson((await runAgt(["list"])).stdout);
    expect(list).toHaveLength(3);

    // Filter by status: open (todo + in-progress + idea)
    list = parseJson((await runAgt(["list", "--status", "open"])).stdout);
    expect(list).toHaveLength(3);

    // Complete child1
    assertSuccess(await runAgt(["update", child1Id, "--status", "done"]));

    // Filter by status: open still has 3 (done stays in index.open)
    list = parseJson((await runAgt(["list", "--status", "open"])).stdout);
    expect(list).toHaveLength(3);

    // Filter by specific status: todo should have 1 (parent only)
    list = parseJson((await runAgt(["list", "--status", "todo"])).stdout);
    expect(list).toHaveLength(1);

    // Verify children via list --parentId
