    expect(child1View.status).toBe("closed");

    const child2View = parseJson(
      (await runAgt(["view", child2Id])).stdout,
    );
    // child2 was in-progress, NOT done — not auto-closed
    expect(child2View.status).toBe("in-progress");
  });
});

