/**
 * E2E: push — Type A tests (git push operations)
 *
 * Tests push behavior using a shared worktree that's initialized in beforeEach.
 */
import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import {
  E2E_GIT_BRANCH,
  assertSuccess,
  initE2EWorktree,
  parseJson,
  runAgt,
  teardownE2EWorktree,
} from "./setup";

describe("E2E: push", () => {
  beforeEach(async () => {
    await teardownE2EWorktree(E2E_GIT_BRANCH);
    await initE2EWorktree(E2E_GIT_BRANCH);
  });

  afterEach(async () => {
    await teardownE2EWorktree(E2E_GIT_BRANCH);
  });

  test("push with no changes returns no changes to sync", async () => {
    const result = await runAgt(["push"]);

    expect(result.exitCode).toBe(0);

    const parsed = parseJson(result.stdout);
    expect(parsed.result).toBe("OK");
    expect(parsed.synced).toBe(false);
    expect(parsed.message).toContain("No changes");
  });

  test("push after creating issue syncs successfully", async () => {
    // Create an issue to generate changes
    const createResult = await runAgt(["create", "Test Issue"]);
    assertSuccess(createResult);

    const result = await runAgt(["push"]);

    expect(result.exitCode).toBe(0);

    const parsed = parseJson(result.stdout);
    expect(parsed.result).toBe("OK");
    expect(parsed.synced).toBe(true);
  });

  test("push with custom message", async () => {
    await runAgt(["create", "Test Issue"]);

    const result = await runAgt(["push", "--message", "custom push message"]);

    expect(result.exitCode).toBe(0);

    const parsed = parseJson(result.stdout);
    expect(parsed.result).toBe("OK");
    expect(parsed.synced).toBe(true);
  });
});

