  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  unlinkSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { spawn } from "bun";
import { expect } from "bun:test";

// ─── Constants ───────────────────────────────────────────────────────

/** Path to the CLI binary (TypeScript source) */
const BIN_PATH = join(import.meta.dir, "..", "..", "src", "bin.ts");

