    const content = readFileSync(gitignorePath, "utf-8");
    if (!content.split("\n").some((line) => line.trim() === entry)) {
      const suffix = content.endsWith("\n") ? "" : "\n";
      writeFileSync(gitignorePath, content + suffix + entry + "\n");
