  const worktreePath = join(validationDir, `.${branch}`);

  // Remove worktree
  try {
    execSync(`git worktree remove -f "${worktreePath}"`, {
      cwd: projectRoot,
      stdio: "pipe",
    });
  } catch {
    // Worktree may not exist — ignore
