  // Prune stale worktree entries
  try {
    execSync("git worktree prune", { cwd: projectRoot, stdio: "pipe" });
  } catch {
    // Ignore
  }

  // Delete local branch
  try {
    execSync(`git branch -D ${gitBranch}`, {
      cwd: projectRoot,
      stdio: "pipe",
    });
  } catch {
    // Branch may not exist — ignore
